function o(t){return`${t.toLocaleString("fr-FR",{minimumFractionDigits:2,maximumFractionDigits:2})} €`}function u(t){return`${t.toLocaleString("fr-FR",{minimumFractionDigits:1,maximumFractionDigits:1})} %`}function m(t,i){return t.ingredients.reduce((a,n)=>{const r=i.get(n.ingredientId);return a+(r?n.quantite*r.prixUnitaireHT:0)},0)+t.consommablesHT}function c(t,i){return t/(1+i/100)}function s(t,i){return t===0?0:(t-i)/t*100}export{u as a,m as c,o as f,s as m,c as p};
